import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 40, C: 101, D: 19.99, E: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

const post = async (base, items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: res.status, body: await res.json() }
}

// Each case pins CURRENT behaviour. Cases marked SUSPECT may be bugs; if you
// fix them, update the expectation deliberately.
const cases = [
  ['single small item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines are summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], 60],
  ['exactly 100 gets no discount (threshold is strict >)', [{ sku: 'A', qty: 10 }], 100],
  ['exactly 100 from a single sku', [{ sku: 'E', qty: 1 }], 100],
  ['120 gets 10% off', [{ sku: 'B', qty: 3 }], 108],
  ['SUSPECT: 101 -> 90.9 is floored to 90 (cents dropped)', [{ sku: 'C', qty: 1 }], 90],
  ['SUSPECT: 1010 -> 909', [{ sku: 'C', qty: 10 }], 909],
  ['SUSPECT: fractional prices are floored, 19.99 -> 19', [{ sku: 'D', qty: 1 }], 19],
  ['SUSPECT: 19.99*6=119.94 -> 107.946 -> 107', [{ sku: 'D', qty: 6 }], 107],
]

for (const [name, items, total] of cases) {
  test(`total: ${name}`, () => withApp(async (base) => {
    const { status, body } = await post(base, items)
    assert.equal(status, 201)
    assert.equal(body.total, total)
  }))
}

test('stored order returns same total', () => withApp(async (base) => {
  const { body } = await post(base, [{ sku: 'B', qty: 3 }])
  const got = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.equal(got.total, 108)
}))

test('empty items rejected', () => withApp(async (base) => {
  assert.equal((await post(base, [])).status, 400)
}))
EOF
